using System.IO;using System.Linq;using UnityEngine;
namespace LostRealmsOW{public static class TownInteriorSurvey {
 public static void FixLamps(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.ActiveTerrain);string path="Assets/Resources/World/Realm/RealmPlacements.json";var set=JsonUtility.FromJson<OWPlacementSet>(File.ReadAllText(path));var kept=new System.Collections.Generic.List<OWPlacement>();int moved=0,removed=0;bool moveNorthHouse=Vector2.Distance(new Vector2(set.Get(40).pos.x,set.Get(40).pos.z),new Vector2(28.258f,69.470f))<.1f;for(int i=0;i<set.Count;i++){var p=set.Get(i);if(moveNorthHouse&&(i==40||i==41)){p.pos+=new Vector3(-.258362f,0,12.529533f);p.pos.y=gm.ActiveTerrain.SampleHeight(p.pos)+gm.ActiveTerrain.transform.position.y;}
 if(i<52){Vector2 delta=Vector2.zero;if(i>=22&&i<=24)delta=new Vector2(2.244045f,3.203586f);else if(i>=25&&i<=27)delta=new Vector2(3.129411f,3.069481f);else if(i>=10&&i<=12)delta=new Vector2(-2.621288f,3.621246f);else if(i>=36&&i<=39)delta=new Vector2(4.228321f,8.631929f);
 bool original=(i==22&&Vector2.Distance(new Vector2(p.pos.x,p.pos.z),new Vector2(-8.244f,47.796f))<.1f)||(i==25&&Vector2.Distance(new Vector2(p.pos.x,p.pos.z),new Vector2(4.871f,-46.069f))<.1f)||(i==10&&Vector2.Distance(new Vector2(p.pos.x,p.pos.z),new Vector2(-16.379f,-44.621f))<.1f)||(i==36&&Vector2.Distance(new Vector2(p.pos.x,p.pos.z),new Vector2(59.772f,16.368f))<.1f);
 if(original||((i==23||i==24||i==26||i==27||i==11||i==12||i==37||i==38||i==39)&&delta!=Vector2.zero&&set.generated!="Codex town clearance 2026-11-01")){p.pos+=new Vector3(delta.x,0,delta.y);p.pos.y=gm.ActiveTerrain.SampleHeight(p.pos)+gm.ActiveTerrain.transform.position.y;}}
 if(p.kind==OWPlaceKind.Lamp){if(kept.Any(q=>q.kind==p.kind&&(q.pos-p.pos).sqrMagnitude<.25f)){removed++;continue;}var old=new Vector2(p.pos.x,p.pos.z);Vector2 target=old;if(Vector2.Distance(old,new Vector2(0,25))<7)target=new Vector2(old.x<0?-8:8,23);else if(Vector2.Distance(old,new Vector2(-16.17f,17.25f))<.6f)target=new Vector2(-8,16);else if(Vector2.Distance(old,new Vector2(-21.91f,11.96f))<.6f)target=new Vector2(-25,12);else if(Vector2.Distance(old,new Vector2(18.13f,14.83f))<.6f)target=new Vector2(22.5f,15);else if(Vector2.Distance(old,new Vector2(23.58f,-8.83f))<.6f)target=new Vector2(20,-10);if(target!=old){p.pos=new Vector3(target.x,0,target.y);p.pos.y=gm.ActiveTerrain.SampleHeight(p.pos)+gm.ActiveTerrain.transform.position.y;moved++;}}kept.Add(p);}File.WriteAllText(path,JsonUtility.ToJson(Stamp(kept),true));Debug.Log("[TownLayout] moved "+moved+" lamps; removed duplicates "+removed);}
 static OWPlacementSet Stamp(System.Collections.Generic.List<OWPlacement> list){var s=OWPlacementSet.Pack(list);s.generated="Codex town clearance 2026-11-01";return s;}
 public static void Run(){var lines=new System.Collections.Generic.List<string>();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>()){if(new Vector2(t.position.x,t.position.z).magnitude>70)continue;string n=t.name.ToLowerInvariant();if(!(n.Contains("tower")||n.Contains("house")||n.Contains("building")||n.Contains("lamp")||n.Contains("gate_")||n.Contains("hall")))continue;if(!t.GetComponentsInChildren<Renderer>().Any())continue;var b=OpenWorldMaterialHelper.ComputeRendererBounds(t);lines.Add(t.name+" parent="+(t.parent?t.parent.name:"")+" pos="+t.position+" bounds="+b);}
 lines.Add("Residents="+UnityEngine.Object.FindObjectsByType<OpenWorldNPC>().Count(n=>n.NpcId.StartsWith("interior-resident-"))+" chests="+UnityEngine.Object.FindObjectsByType<OpenWorldCollectible>().Count(c=>c.PersistentId.StartsWith("chest:interior:")));foreach(var p in OpenWorldTownInteriors.Residents)lines.Add("Resident "+p);foreach(var p in OpenWorldTownInteriors.Chests)lines.Add("Chest "+p);File.WriteAllLines("Docs/QA/TOWN_INTERIOR_SURVEY.txt",lines);Debug.Log("[TownSurvey] "+lines.Count+" structures surveyed");}

 public static void Validate(){var lines=new System.Collections.Generic.List<string>();void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);}var roots=UnityEngine.Object.FindObjectsByType<Transform>().Where(t=>t.parent&&new Vector2(t.position.x,t.position.z).magnitude<80&&((t.parent.name=="Architecture & Cliffs"&&(t.name.Contains("house")||t.name.Contains("shed")||t.name.Contains("tavern")||t.name.Contains("armory")))||(t.parent.name=="CapitalOuterBuildings"&&t.name.Contains("building"))||(t.parent.name=="HubVistaAndSkyArchipelago"&&(t.name.Contains("building")||t.name=="OW_Tower"))||(t.parent.name=="VerdantOpenWorld"&&t.name.Contains("OW_rpgpp_lt_shed"))||t.name.Contains("Blacksmith_Building")&&t.parent.name=="Blacksmith_RoyalForge_Workshop")).ToArray();
 for(int i=0;i<roots.Length;i++)for(int j=i+1;j<roots.Length;j++){var a=roots[i];var b=roots[j];var aa=OpenWorldMaterialHelper.ComputeRendererBounds(a);var bb=OpenWorldMaterialHelper.ComputeRendererBounds(b);aa.Expand(-.12f);bb.Expand(-.12f);Check(!aa.Intersects(bb),"structures separated: "+a.name+a.position+" / "+b.name+b.position);}
 var arch=GameObject.Find("OW_Arch");foreach(var lamp in UnityEngine.Object.FindObjectsByType<Transform>().Where(t=>t.parent&&t.parent.name=="Streamed Detail"&&t.name.Contains("lantern_post")&&new Vector2(t.position.x,t.position.z).magnitude<60)){var lb=OpenWorldMaterialHelper.ComputeRendererBounds(lamp);foreach(var structure in roots){var b=OpenWorldMaterialHelper.ComputeRendererBounds(structure);b.Expand(-.1f);Check(!b.Intersects(lb),"lamp clear: "+lamp.position+" / "+structure.name);}if(arch)Check(!lb.Intersects(OpenWorldMaterialHelper.ComputeRendererBounds(arch.transform)),"lamp clear of arch: "+lamp.position);}
 var residents=UnityEngine.Object.FindObjectsByType<OpenWorldNPC>().Where(n=>n.NpcId.StartsWith("interior-resident-")).ToArray();Check(residents.Length>=4,"four indoor residents present");foreach(var npc in residents){var cc=npc.GetComponent<CapsuleCollider>();Check(cc&&!cc.isTrigger,"resident solid capsule "+npc.transform.position);var p=npc.transform.position;Check(!Physics.OverlapCapsule(p+Vector3.up*.36f,p+Vector3.up*1.48f,.29f,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(npc.transform)),"resident body clear of walls/floor "+p);float min=999;foreach(var r in npc.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();r.BakeMesh(mesh,false);foreach(var v in mesh.vertices)min=Mathf.Min(min,r.transform.TransformPoint(v).y);UnityEngine.Object.DestroyImmediate(mesh);}Check(min>p.y-.15f&&min<p.y+.12f,"resident visible feet grounded "+min.ToString("F2")+" root="+p.y.ToString("F2"));}
 Check(UnityEngine.Object.FindObjectsByType<OpenWorldCollectible>().Count(c=>c.PersistentId.StartsWith("chest:interior:"))>=4,"four persistent house chests");File.WriteAllLines("Docs/QA/TOWN_LAYOUT_VALIDATION.txt",lines);Debug.Log(string.Join("\n",lines.Where(l=>l.StartsWith("FAIL")))+"\nChecks "+lines.Count);}
 public static void FocusArch(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);gm.CameraRig.enabled=false;Camera.main.transform.position=new Vector3(10,11,13);Camera.main.transform.LookAt(new Vector3(0,9,27));}
 public static void FocusResident(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);var npc=UnityEngine.Object.FindObjectsByType<OpenWorldNPC>().First(n=>n.NpcId.StartsWith("interior-resident-"));gm.CameraRig.enabled=false;Camera.main.transform.position=npc.transform.position+new Vector3(1.7f,1.7f,-1.8f);Camera.main.transform.LookAt(npc.transform.position+Vector3.up);}
 public static void FocusChest(){var gm=UnityEngine.Object.FindObjectsByType<OpenWorldManager>().First(g=>g.Hero);var chest=UnityEngine.Object.FindObjectsByType<OpenWorldCollectible>().First(c=>c.PersistentId.StartsWith("chest:interior:"));gm.CameraRig.enabled=false;Camera.main.transform.position=chest.transform.position+new Vector3(.06f,1.5f,-.06f);Camera.main.transform.LookAt(chest.transform.position+Vector3.up*.4f);}
}}
